  }
  /* The shrouded column itself is repainted white in that same open state */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_columns.sidebar_open .primary_column {
    background-color: transparent !important;
  }
  /* Faceted filter blocks + tag-card image bands ship a light gray_back */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .facet_group,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .tag_cell .header_image {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
  }
  /* Segmented toggle (search "Type: Projects/Jams") — white pill, short enough
     to slip the surface scan's height gate; keep the red active underline. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .segmented_links {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .segmented_link { color: #8b949e !important; }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .segmented_link.active { color: #e6edf3 !important; }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .facet_group_label,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .facet_panel_hint,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .facet_panel_note,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .results_label,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .stats_line,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .control_label,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_count,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .games_count,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .games_count strong,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .mobile_filter_btn,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_top_tags,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_top_tags a {
    color: #8b949e !important;
  }
  /* Rating count beside the stars in every game grid ships itch's #606060 (~2.2:1 here) */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_rating,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .rating_count {
    color: #8b949e !important;
  }

  /* ==== Sale / promotion pages (itch.io/s/<id>/<slug>, itch.io/sale-explorer) ==== */
  /* The sale hero splits into a dark details half and a var(--itchio_white_back) product
     half; the buy row is the same white. Both carry our light text -> white-on-white. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .promotion_page .game_column,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .promotion_page .promotion_buy_row {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Host byline, discount rate and end date all ship #606060 on the dark half */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .promotion_page .promotion_host,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .promotion_page .promotion_meta,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .promotion_page .sale_rate,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .promotion_page .percent_off,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .promotion_page .promotion_dates,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .promotion_page .date_format {
    color: #8b949e !important;
  }
  /* Countdown digits are the loudest thing in the buy row natively and ship #606060 */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .promotion_page .countdown .block_value {
    color: #e6edf3 !important;
  }
  /* "More from this sale" banner fills var(--itchio_target_bg) #D7FCAF; keep the green
     read as a positive tint but at a dark-fit value. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .sale_explorer_page .similar_banner {
    background-color: #1b2a17 !important;
    border-color: #2d333b !important;
  }

  /* Below itch's own 650px breakpoint the devlog feed drops the desktop grid and becomes a
     stacked card list, and only THERE does it paint the strip #f4f4f4 and each post #fff —
     at desktop width both are transparent, so a desktop-only pass never sees it and our light
     body text lands white-on-white. Scoped to the same query so desktop is untouched. */
  @media (max-width: 650px) {
    body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .blog_post_grid_widget {
      background-color: transparent !important;
    }
    body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .blog_post_grid_widget .blog_post {
      background-color: #1c2128 !important;
      border-color: #2d333b !important;
    }
  }

  /* ==== 404 / message pages ==== */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .not_found_page,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .page_message,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .page_message h2 {
    color: #e6edf3 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .art_credits,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .art_credits a { color: #8b949e !important; }
  /* The 404 error art is a transparent PNG whose black cap/outlines and hand-lettered
     "NOT FOUND" caption are drawn for a light page; the broad .image_wrapper dark rule
     renders them black-on-dark. Restore a light backing so the art reads as designed. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .not_found_page .image_wrapper {
    background-color: #e9ebee !important;
  }

  /* ==== Lightbox dialogs (login prompt, share sheet, image viewer) ==== */
  /* itch mounts these as real <dialog> nodes that only exist once opened, so no load-time
     scan reaches them. Native is var(--itchio_white_back) ringed by #dadada/white, which
     leaves our light heading colour writing white-on-white. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) dialog {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    box-shadow: 0 0 0 2px #2d333b, 0 0 20px rgba(0, 0, 0, 0.6) !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) dialog p,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) dialog li {
    color: #c4cdd6 !important;
  }
  /* Its backdrop is a separate #lightbox_shroud div filled var(--itchio_ui_bg) #40434E at
     0.8 — lighter than our page, so opening a dialog WASHES the page instead of dimming it. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) #lightbox_shroud {
    background-color: #05080c !important;
  }

  /* ==== Documentation (itch.io/docs/…) ==== */
  /* Whole page type: the article shell and its content column are var(--itchio_white_back)
     and the nav band is painted by an inset 50vw box-shadow (no element to catch it), so
     every heading we lightened rendered white-on-white. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page {
    background-color: #14181d !important;
    box-shadow: inset 50vw 0 0 #1a1f26 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .content_column {
    background-color: #14181d !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .nav_column .column_header,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .social_nag {
    color: #8b949e !important;
  }
  /* Every sidebar entry carries a transparent 1px underline as a spacer and the CURRENT
     article colours it #da2c49 — the blanket border reset paints all 39 the same grey, so
     the whole rail underlines and the "you are here" mark disappears. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .nav_column .tab_btn a {
    border-bottom-color: transparent !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .nav_column .tab_btn.selected a {
    color: #fa7d8c !important;
    border-bottom-color: #fa7d8c !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .mobile_menu,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .recover_form,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .text_content blockquote,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .text_content code,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .text_content .navigation h3 {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  /* <pre> already ships its own dark block; its inner <code> must stay see-through */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .text_content pre > code {
    background-color: transparent !important;
  }
  /* API reference endpoint headers bleed their fill past the box with a 10px #F4F4F4 spread */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .text_content h3 code {
    box-shadow: 0 0 0 10px #1c2128 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page .text_content p img.showcase {
    box-shadow: 0 0 20px rgba(0, 0, 0, 0.6) !important;
  }
  /* Anchor-target heading highlight ships #D7FCAF, painted as fill AND a 10px spread */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .knowledge_base_article_page h2.highlight {
    background-color: #22331a !important;
    box-shadow: 0 0 0 10px #22331a !important;
  }
  /* The app manual under /docs/itch/ is a separate honkit build with its own stylesheet:
     white body, #fafafa summary rail, and #333/#000 copy that goes dark-on-dark once we
     darken them. body carries .book_layout_widget (never a creator layout). */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book-summary {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book-body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .markdown-section {
    color: #c4cdd6 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) #book-search-input {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) #book-search-input input {
    color: #e6edf3 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book-body code,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book-body pre {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* "Return to app" sits on itch's #BB4F4F band and is natively white with a white hairline;
     the blanket accent + border reset drop it to 1.9:1 inside a near-black outline. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book_page_header .return_link {
    color: #ffffff !important;
    border-color: rgba(255, 255, 255, 0.8) !important;
  }
  /* honkit's font/theme picker: a #fafafa flyout whose generic .button class our brand-red
     button rule hijacks into a grid of red blocks. Click-gated, so no load-time scan sees it. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book_page .dropdown-menu {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book_page .dropdown-menu .button {
    background-color: transparent !important;
    color: #c4cdd6 !important;
    /* itch's .button pairs its red fill with a red text-shadow; without the fill it halos */
    text-shadow: none !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book_page .dropdown-menu .button:hover {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  /* Its pointer is a pair of CSS triangles; the blanket border reset fills the transparent
     sides, so the caret renders as a solid rectangle above the flyout. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book_page .dropdown-caret .caret-outer,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book_page .dropdown-caret .caret-inner {
    border-left-color: transparent !important;
    border-right-color: transparent !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book_page .dropdown-caret .caret-outer {
    border-bottom-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .book_page .dropdown-caret .caret-inner {
    border-bottom-color: #1c2128 !important;
  }

  /* ==== Footer ==== */
  .footer .primary,
  .footer .secondary,
  .footer .copyright { color: #8b949e !important; }
  .footer a { color: #a8b0b8 !important; }
  .footer a:hover { color: #e6edf3 !important; }

  /* Horizontal carousel scroll-fade paddles (home rows, profile "Creator of") ship a
     white background-image gradient — a scroll-fade indicator that washes to white over
     cover art. Remap the gradient stops to the page base so it fades to dark. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .paddle_next {
    background-image: linear-gradient(to right, rgba(20, 24, 29, 0) 0%, #14181d 50%, #14181d 100%) !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .paddle_prev {
    background-image: linear-gradient(to right, #14181d 0%, #14181d 50%, rgba(20, 24, 29, 0) 100%) !important;
  }

  /* ==== Large promo / hero sections ==== */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .large_promo_section { background-color: #0d1117 !important; }
  /* Featured-game promo panel ships a 30% white overlay -> washed grey on dark; darken it */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .youtube_game_promo_banner_widget {
    background-color: rgba(13, 17, 23, 0.55) !important;
  }
  /* The mobile variant is a position:fixed bottom bar backed by SOLID black, not a translucent
     overlay — its gradient fades to transparent at the right, so a translucent fill here lets
     the grid scroll through it. Must stay opaque. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .youtube_mobile_banner_widget {
    background-color: #0d1117 !important;
  }
}
